/*
 * As peças que mostram o perfil estendido. Todas devolvem `null` quando o
 * campo está vazio ou desligado, então dá para usá-las em qualquer lugar sem
 * checar antes — é o que o hero do perfil e o cartão do tópico devem fazer.
 */
import app from 'flarum/forum/app';
import Icon from 'flarum/common/components/Icon';
import { t } from '../../utils/settings';
import { cssImage, formatBirthday, isBirthdayToday, userBirthday, userCardBackgroundUrl, userCoverPosition, userCoverUrl, userStatus, userTitle } from './data';

/** Emoji padrão de quem pôs só a frase, como o Discourse faz. */
export const DEFAULT_STATUS_EMOJI = '💬';

/** "até 15:30" no mesmo dia, "até sex., 18 out." depois. */
export function statusUntilLabel(until) {
  const now = new Date();
  const sameDay = until.toDateString() === now.toDateString();
  const locale = app.data.locale || undefined;
  const when = sameDay ? until.toLocaleTimeString(locale, {
    hour: '2-digit',
    minute: '2-digit'
  }) : until.toLocaleDateString(locale, {
    weekday: 'short',
    day: 'numeric',
    month: 'short'
  });
  return t('profile.status.until', {
    when
  });
}

/** Texto inteiro do status, para o title e o leitor de tela. */
export function statusLabel(status) {
  return [status.text, status.until ? statusUntilLabel(status.until) : null].filter(Boolean).join(' · ') || t('profile.status.label');
}

/** O emoji do status ao lado do nome (posts, cabeçalho, cartão). */
export function StatusEmoji(user, className = '') {
  const status = userStatus(user);
  if (!status) return null;
  const label = statusLabel(status);
  return m("span", {
    className: `CanelaStatusEmoji ${className}`.trim(),
    title: label,
    "aria-label": label,
    role: "img"
  }, status.emoji || DEFAULT_STATUS_EMOJI);
}

/** Linha do status no cartão: emoji, frase e até quando. */
export function StatusLine(user) {
  const status = userStatus(user);
  if (!status) return null;
  return m("div", {
    className: "CanelaProfileStatus"
  }, m("span", {
    className: "CanelaProfileStatus-emoji",
    "aria-hidden": "true"
  }, status.emoji || DEFAULT_STATUS_EMOJI), status.text && m("span", {
    className: "CanelaProfileStatus-text"
  }, status.text), status.until && m("span", {
    className: "CanelaProfileStatus-until"
  }, statusUntilLabel(status.until)));
}
export function TitleLine(user) {
  const title = userTitle(user);
  return title ? m("div", {
    className: "CanelaProfileTitle"
  }, title) : null;
}
export function BirthdayFact(user) {
  const birthday = userBirthday(user);
  if (!birthday) return null;
  const today = isBirthdayToday(birthday);
  return m("span", {
    className: `CanelaProfileFact CanelaProfileFact--birthday${today ? ' is-today' : ''}`
  }, m(Icon, {
    name: "fas fa-cake-candles"
  }), m("span", null, today ? t('profile.birthday.today') : formatBirthday(birthday)));
}

/**
 * Variáveis CSS das imagens, para pôr no `style` do elemento do perfil ou do
 * cartão. `--canela-cover` é a que o hero do perfil já lê como camada de cima
 * da capa; `--canela-user-cover` e `--canela-user-card-bg` ficam para quem
 * quiser usar só uma delas.
 */
export function profileImageStyle(user) {
  const style = {};
  const cover = userCoverUrl(user);
  const card = userCardBackgroundUrl(user);
  if (cover) {
    style['--canela-cover'] = cssImage(cover);
    style['--canela-user-cover'] = cssImage(cover);
  }
  if (card) style['--canela-user-card-bg'] = cssImage(card);

  // A posição da forumaker vale para a capa e para o cartão (a miniatura é a
  // mesma imagem reduzida). As regras do LESS caem em `center` sem ela.
  const position = userCoverPosition(user);
  if (position !== null && (cover || card)) style['--canela-cover-position'] = `center ${position}%`;
  return style;
}

/**
 * Tudo junto, na ordem do cartão de usuário do Discourse: status, título e o
 * aniversário. Para o cartão do tópico, que é um componente próprio e não um
 * UserCard.
 */
export function ProfileCardExtras(user) {
  const facts = [BirthdayFact(user)].filter(Boolean);
  const parts = [StatusLine(user), TitleLine(user), facts.length ? m("div", {
    className: "CanelaProfileFacts"
  }, facts) : null].filter(Boolean);
  return parts.length ? m("div", {
    className: "CanelaProfileExtras"
  }, parts) : null;
}
flarum.reg.add('lcoy-roselle', 'forum/features/profile/components', { DEFAULT_STATUS_EMOJI: DEFAULT_STATUS_EMOJI,statusUntilLabel: statusUntilLabel,statusLabel: statusLabel,StatusEmoji: StatusEmoji,StatusLine: StatusLine,TitleLine: TitleLine,BirthdayFact: BirthdayFact,profileImageStyle: profileImageStyle,ProfileCardExtras: ProfileCardExtras, });